        const gx = gradients[3 * index], gy = gradients[3 * index + 1], gz = gradients[3 * index + 2];
        if (!(Number.isFinite(gx) && Number.isFinite(gy) && Number.isFinite(gz))) continue;
        const distance2 = dx * dx + dy * dy + dz * dz;
        if (distance2 === 0) return { value: values[index], gradient: [gx, gy, gz] };
        const weight = 1 / distance2;
