  function onHoverMove(ev) {
    if (!ev) return;
    if (cadViewport && cadViewport.isPicking()) { clearHoverOutline(); return; }
    if (selectMode !== "element") {
      clearHoverOutline();
      return;
    }
    if (!meshShell && !meshSolid && (!Array.isArray(meshSolidChunks) || meshSolidChunks.length === 0)) {
      clearHoverOutline();
      return;
    }
    const rect = canvas.getBoundingClientRect();
    mouse.x = (ev.clientX - rect.left) / rect.width * 2 - 1;
    mouse.y = -((ev.clientY - rect.top) / rect.height) * 2 + 1;
    raycaster.setFromCamera(mouse, camera);
    const pick = pickVisibleElementDataAtClientPoint(ev.clientX, ev.clientY);
    const firstHit = pick ? pick.hit : null;
    if (!firstHit) {
      clearHoverOutline();
      return;
    }
    let hoverMesh = null;
    let obj = firstHit.object;
    while (obj && !(obj.userData && obj.userData.triOwnerEid)) obj = obj.parent;
    if (obj && obj.userData && obj.userData.triOwnerEid) {
      hoverMesh = obj;
    } else if (meshShell && isDescendantObject(firstHit.object, meshShell) && meshShell.userData && meshShell.userData.triOwnerEid) {
      hoverMesh = meshShell;
    } else if (meshSolid && isDescendantObject(firstHit.object, meshSolid) && meshSolid.userData && meshSolid.userData.triOwnerEid) {
      hoverMesh = meshSolid;
    }
    if (!hoverMesh || !hoverMesh.userData || !hoverMesh.userData.triOwnerEid) {
      clearHoverOutline();
      return;
    }
    const faceIndex = firstHit.faceIndex;
    if (typeof faceIndex !== "number" || faceIndex < 0 || faceIndex >= hoverMesh.userData.triOwnerEid.length) {
      clearHoverOutline();
      return;
    }
    const eid = hoverMesh.userData.triOwnerEid[faceIndex] >>> 0;
    setHoverOutlineForElement(hoverMesh, eid);
  }
